import numpy as np
from scipy.linalg import expm
from scipy.signal import tf2ss
from pathlib import Path
import json
Ts=1e-4;m=.6;Kf=20;tau=1e-4;tf=1e-4;fnotch=np.sqrt(64e6/m)/(2*np.pi)
aSense=np.exp(-Ts/tf)

def coeff_lowpass(f,damping):
 w=np.tan(np.pi*f*Ts);den=np.array([1+2*damping*w+w*w,2*(w*w-1),1-2*damping*w+w*w]);num=w*w*np.array([1.,2,1])/den[0];den=den/den[0];return num,den

def coeff_notch(f,zz,zp):
 w=np.tan(np.pi*f*Ts);den=np.array([1+2*zp*w+w*w,2*(w*w-1),1-2*zp*w+w*w]);num=np.array([1+2*zz*w+w*w,2*(w*w-1),1-2*zz*w+w*w])/den[0];den/=den[0];return num,den

def tf_sum(b1,a1,b2,a2):
 t1=np.polymul(b1,a2);t2=np.polymul(b2,a1)
 return np.polyadd(t1,t2),np.polymul(a1,a2)

def control_coeff(kp=.03,ki=20,kd=0,lp=None,notch=None,slope=0,mu=.3,geometry_loop=True):
 bp=np.array([Kf*kp,Kf*(ki*Ts-kp)]);ap=np.array([1.,-1])
 if kd:
  ad=np.exp(-Ts/.0003);bd=Kf*kd*(1-ad)/Ts*np.array([1.,-1]);dd=np.array([1.,-ad]);bp,ap=tf_sum(bp,ap,bd,dd)
 if lp:
  b,a=coeff_lowpass(*lp);bp=np.polymul(bp,b);ap=np.polymul(ap,a)
 geom=slope*(slope+mu)/np.sqrt(1+slope*slope) if geometry_loop else 0.
 b,a=tf_sum(bp,ap,[geom],[1.])
 if notch:
  bn,an=coeff_notch(*notch);b=np.polymul(b,bn);a=np.polymul(a,an)
 return b,a

def plant_coeff(k=64e6,friction=2,cellc=0,slope=0,mu=.3):
 wn=np.sqrt(k/m);A=np.array([[0,wn,0],[-wn,-(friction+cellc)/m,wn],[0,0,-1/tau]]);B=np.array([[0.],[0.],[1/tau]])
 E=np.zeros((4,4));E[:3,:3]=A;E[:3,3:]=B;D=expm(E*Ts);Ap=D[:3,:3];Bp=D[:3,3:]
 axialScale=(1-mu*slope)/np.sqrt(1+slope*slope);Cp=np.array([[1,cellc*wn/k,0]])/axialScale
 return Ap,Bp,Cp,wn

def closed(k=64e6,friction=2,cellc=0,kp=.03,ki=20,kd=0,lp=None,notch=None,slope=0,mu=.3,geometry_loop=True):
 b,a=control_coeff(kp,ki,kd,lp,notch,slope,mu,geometry_loop);Ac,Bc,Cc,Dc=tf2ss(b,a);Ap,Bp,Cp,wn=plant_coeff(k,friction,cellc,slope,mu)
 nc=len(Ac);A=np.zeros((4+nc,4+nc));A[:3,:3]=Ap;A[:3,3:4]=-Bp@Dc;A[:3,4:]=-Bp@Cc;A[3:4,:3]=(1-aSense)*Cp;A[3,3]=aSense;A[4:,3:4]=Bc;A[4:,4:]=Ac
 poles=np.linalg.eigvals(A);rate=np.log(poles.astype(complex))/Ts;frequencies=np.abs(rate.imag)/(2*np.pi);cand=(frequencies>500)&(frequencies<3500);srate=rate[cand];spole=poles[cand];mode=np.argmax(srate.real) if any(cand) else None
 row={'max_pole_radius':float(max(abs(poles))),'stable':bool(max(abs(poles))<1),'largest_growth_rate_per_s':float(max(rate.real)),'structural_mode':None,'parameters':{'k_N_m':k,'friction_tangent_N_s_m':friction,'cell_damping_N_s_m':cellc,'kp_A_N':kp,'ki_A_N_s':ki,'kd_A_s_N':kd,'feedback_lp':lp,'total_current_notch':notch,'slope':slope,'mu':mu,'direct_geometry_force_loop':geometry_loop}}
 if mode is not None: row['structural_mode']={'frequency_Hz':float(abs(srate[mode].imag)/(2*np.pi)),'growth_rate_per_s':float(srate[mode].real),'pole_radius':float(abs(spole[mode])),'equivalent_damping_ratio':float(-srate[mode].real/abs(srate[mode]))}
 row['poles']=[{'real':float(p.real),'imag':float(p.imag),'radius':float(abs(p))} for p in poles]
 return row,(Ap,Bp,Cp,b,a,A)

