exec(open('/tmp/acf-structural-control-review.py').read().split('strategies=')[0])
M=2.6;ms=2.;Nfreq=65536
w=(np.arange(Nfreq)+.5)*np.pi/Nfreq;z=np.exp(1j*w);freq=w/(2*np.pi*Ts)
Hsensor=(1-aSense)/(z-aSense)
noiseRms=.0123;noiseRaw=noiseRms/np.sqrt((1-aSense)/(1+aSense));q=.00468
Sacc=noiseRaw**2*abs(Hsensor)**2+q*q/12
ad=np.exp(-Ts/.0003);derivative=(1-ad)/Ts*(z-1)/(z-ad)
strategies=[('current100_lp'+str(f),1e-4,f) for f in [400,600,800,1000,1200]]+[(f'current{int(tt*1e6)}_lp1000',tt,1000) for tt in [5e-5,1.5e-4,2e-4]]
ks=[20e6,40e6,51.2e6,64e6,80e6,96e6,110e6];bs=[2,5,50,200,1002];ss=[0,.34346004134,-.15,-.34346004134];mus=[.3,.5]
allrows=[];summary=[];noise=[];frequency=[];gp_cache={}
for name,tt,f in strategies:
 tau=tt;rows=[]
 for kk in ks:
  for bb in bs:
   for slope in ss:
    for mu in mus:
     row,_=closed(k=kk,friction=bb,kp=.06,ki=20,lp=(f,1.5),slope=slope,mu=mu,geometry_loop=False)
     row['strategy']=name;row['current_time_s']=tt;rows.append(row)
 allrows.extend(rows)
 group={}
 for kk in ks:
  rr=[r for r in rows if r['parameters']['k_N_m']==kk];worst=max(rr,key=lambda r:r['largest_growth_rate_per_s']);group[str(int(kk))]={'stable_points':sum(r['stable'] for r in rr),'points':len(rr),'worst_growth_per_s':worst['largest_growth_rate_per_s'],'worst_parameters':worst['parameters'],'worst_structural_mode':worst['structural_mode']}
 rr=[r for r in rows if r['parameters']['k_N_m']>=40e6];worst=max(rr,key=lambda r:r['largest_growth_rate_per_s']);sm={'strategy':name,'current_time_s':tt,'feedback_LP_Hz':f,'feedback_LP_damping':1.5,'Kp_A_N':.06,'Ki_A_N_s':20,'stable_points_40_to_110M':sum(r['stable'] for r in rr),'points_40_to_110M':len(rr),'worst_growth_40_to_110M_per_s':worst['largest_growth_rate_per_s'],'per_stiffness':group};summary.append(sm)
 cb,ca=control_coeff(kp=.06,ki=20,lp=(f,1.5),geometry_loop=False);Cfb=np.polyval(cb,z)/np.polyval(ca,z)
 for kk in [20e6,40e6,64e6,110e6]:
  row,_=closed(k=kk,friction=2,kp=.06,ki=20,lp=(f,1.5),geometry_loop=False)
  if not row['stable']:
   noise.append({'strategy':name,'cell_stiffness_N_m':kk,'stationary_noise_valid':False,'reason':'Frozen flat loop unstable'});continue
  key=(tt,kk)
  if key not in gp_cache:
   Ap,Bp,Cp,_=plant_coeff(k=kk,friction=2);gp_cache[key]=(Cp@np.linalg.solve(z[:,None,None]*np.eye(3)-Ap,Bp[None,:,:])).reshape(-1)
  G=gp_cache[key];den=1+G*Cfb*Hsensor;Tf=-G*Cfb/den
  for shape,tauFF in [('direct',0),('shaped1ms',.001)]:
   baselineDelay=Ts*aSense/(1-aSense)+.0001+tt+Ts/2
   if tauFF:
    af=np.exp(-Ts/tauFF);prediction=Ts*af/(1-af)+baselineDelay;HF=(1+prediction*derivative)*(1-af)*z/(z-af)
   else:prediction=0.;HF=np.ones_like(z)
   Ta=-G*(ms*Cfb+M*HF)/den
   Pa=abs(Ta)**2*Sacc;Pf=abs(Tf)**2*.02**2;P=Pa+Pf
   rms_a=float(np.sqrt(np.mean(Pa)));rms_f=float(np.sqrt(np.mean(Pf)));rms=float(np.sqrt(np.mean(P)))
   idx=np.argmax(P);bands={}
   for label,lo,hi in [('bump_band_0_100',0,100),('below_500',0,500),('structural_500_3500',500,3500),('above_3500',3500,5000)]:
    mask=(freq>=lo)&(freq<hi);bands[label]=float(np.sqrt(np.sum(P[mask])/Nfreq))
   noise.append({'strategy':name,'cell_stiffness_N_m':kk,'FF_shape':shape,'command_filter_time_s':tauFF,'FF_prediction_time_s':float(prediction),'stationary_noise_valid':True,'noise_force_rms_N':rms,'noise_accel_contribution_rms_N':rms_a,'noise_cell_contribution_rms_N':rms_f,'max_noise_density_frequency_Hz':float(freq[idx]),'integrated_rms_bands_N':bands,'FF_force_request_rms_N':float(M*np.sqrt(np.mean(abs(HF)**2*Sacc)))})
 for freqpoint in [10,20,50,100,300,500,fnotch,np.sqrt(110e6/m)/(2*np.pi)]:
  zz=np.exp(2j*np.pi*freqpoint*Ts);C=np.polyval(cb,zz)/np.polyval(ca,zz);Gc=1/(1+2j*np.pi*freqpoint*tt);LPb,LPa=coeff_lowpass(f,1.5);LP=np.polyval(LPb,zz)/np.polyval(LPa,zz)
  frequency.append({'strategy':name,'frequency_Hz':float(freqpoint),'feedback_controller_gain':float(abs(C)),'feedback_controller_phase_deg':float(np.angle(C,deg=True)),'feedback_LP_gain':float(abs(LP)),'feedback_LP_phase_deg':float(np.angle(LP,deg=True)),'current_continuous_gain':float(abs(Gc)),'current_continuous_phase_deg':float(np.angle(Gc,deg=True))})
